在 Xcode 的 app target 中，创建一个 Objective-C++ 模块。它通过 `NotificationCenter` 将权重数据传递给你的 Swift 代码：

```objectivec showLineNumbers title="RCTNativeWeightPlanStore.mm"
#import "RCTNativeWeightPlanStore.h"

@implementation RCTNativeWeightPlanStore

+ (NSString *)moduleName {
  return @"NativeWeightPlanStore";
}

- (std::shared_ptr<facebook::react::TurboModule>)getTurboModule:
    (const facebook::react::ObjCTurboModule::InitParams &)params {
  return std::make_shared<facebook::react::NativeWeightPlanStoreSpecJSI>(params);
}

- (void)setWeights:(double)currentWeight goalWeight:(double)goalWeight {
  // the AppDelegate updates the weight plan when it receives this notification
  [[NSNotificationCenter defaultCenter] postNotificationName:@"WeightsDidChange"
                                                      object:nil
                                                    userInfo:@{@"current": @(currentWeight),
                                                               @"goal": @(goalWeight)}];
}

@end
```

```swift showLineNumbers title="ios/YourApp/AppDelegate.swift" {1,6-7,13-26}
import AdaptyUI
import UIKit

@main
class AppDelegate: UIResponder, UIApplicationDelegate {
  // the weight plan that your JavaScript code sends
  let weightPlanStore = WeightPlanStore()

  func application(
    _ application: UIApplication,
    didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]? = nil
  ) -> Bool {
    AdaptyUI.setCustomElementsResolver(CustomElementsResolver(weightPlanStore: weightPlanStore))
    // the weights that your JavaScript code sends through the native module
    NotificationCenter.default.addObserver(
      forName: Notification.Name("WeightsDidChange"),
      object: nil,
      queue: .main
    ) { [weightPlanStore] notification in
      guard let currentWeight = notification.userInfo?["current"] as? Double,
            let goalWeight = notification.userInfo?["goal"] as? Double
      else { return }
      MainActor.assumeIsolated {
        weightPlanStore.plan = WeightPlan(currentWeight: currentWeight, goalWeight: goalWeight)
      }
    }
    // the rest of your launch code
    return true
  }
}
```

```kotlin showLineNumbers title="NativeWeightPlanStoreModule.kt"
package com.example.app

import com.example.app.specs.NativeWeightPlanStoreSpec
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.bridge.UiThreadUtil

class NativeWeightPlanStoreModule(reactContext: ReactApplicationContext) :
    NativeWeightPlanStoreSpec(reactContext) {

    override fun getName() = NAME

    override fun setWeights(currentWeight: Double, goalWeight: Double) {
        val app = reactApplicationContext.applicationContext as MainApplication
        // the resolver reads the weight plan on the main thread
        UiThreadUtil.runOnUiThread {
            app.weightPlanStore.plan = WeightPlan(currentWeight, goalWeight)
        }
    }

    companion object {
        const val NAME = "NativeWeightPlanStore"
    }
}
